# Let me pack all non-6 values into a 5x37 grid
grid = [[int(x) for x in line.split()] for line in grid_str.split('\n')]

non_six_values = []
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] != 6:
            non_six_values.append(grid[r][c])

print(f"Total non-6 cells: {len(non_six_values)}")

# Try 5x37 layout
if len(non_six_values) == 5 * 37:
    packed = []
    for i in range(5):
        row = non_six_values[i*37:(i+1)*37]
        packed.append(row)
    print(f"5x37 packed:\n{packed}")
else:
    print(f"Can't pack nicely. {len(non_six_values)} cells doesn't factor as 5*37")

# Try other factors
for x in range(2, 20):
    if len(non_six_values) % x == 0:
        y = len(non_six_values) // x
        print(f"Possible {x}x{y} or {y}x{x} layout")

# Submit packed grid
