# Try: 6 becomes the most common neighbor value
from collections import Counter

grid = [[int(x) for x in line.split()] for line in grid_str.split('\n')]
rows, cols = len(grid), len(grid[0])

output = [row[:] for row in grid]  # Copy

for r in range(rows):
    for c in range(cols):
        if grid[r][c] == 6:
            # Get all 8 neighbors
            neighbors = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        neighbors.append(grid[nr][nc])
            if neighbors:
                # Most common non-6 neighbor
                counts = Counter(n for n in neighbors if n != 6)
                if counts:
                    most_common = counts.most_common(1)[0][0]
                    output[r][c] = most_common

print("Output with 6→most common non-6 neighbor:")
for row in output:
    print(row)

# Check 6 positions per row
